/**
 * Determines the substring between two substrings in a given string, as defined in http://www.ietf.org/rfc/rfc4122.txt.
 * @param {string} str - The string in which to find the substring.
 * @param {string} start - The start substring.
 * @param {string} end - The end substring.
 * @example
 * findBetween("0123456789abcdef0123456789abcdef", "0123456789", "abcdef") === "0123456789abcdef"
 * @throws {Error} If start or end is empty, or if they appear in the string in the wrong order
 * @throws {Error} If the input string is not at least as long as the start plus end substrings
 * @complexity O(n), where n = str.length
 * @see https://github.com/broofa/node-uuid/blob/master/v4.js
 */
function findBetween(str, start, end) {
    // Locate the start position in the string. If it's before the end position,
    // return the string between the two occurrences of the substrings.
    // Otherwise, return the empty string.
    return str.indexOf(start) < str.indexOf(end)
       ? str.substring(str.indexOf(start) + start.length, str.indexOf(end))
        : "";
}
